app = (M / "app.js").read_text(encoding="utf-8")
if "function addPointOverview" not in app:
    sys.exit("Run patch_eyes_cerulean.py first. Nothing was written.")
if "outline-detail" in app:
    print("Already applied — nothing to do.")
    sys.exit(0)

out = {}
for name, pairs in PAIRS.items():
    t = (M / name).read_text(encoding="utf-8")
    for old, new in pairs:
        if t.count(old) != 1:
            sys.exit(f"Could not find the expected text in map/{name} ({old.strip()[:70]!r}). Nothing was written.")
        t = t.replace(old, new)
    out[name] = t
for name, t in out.items():
    (M / name).write_text(t, encoding="utf-8")
print("Done: zoom buttons in the view row, plain dots, OSM on the outlines, faster drawing.")
